// Minimal stand-in for the React types that `componentProp` reads.
declare namespace React {
	type Key = number | string;

	interface ReactElement<P = any> {
		key: Key | null;
		props: P;
	}

	interface ReactPortal extends ReactElement {
		children: ReactNode;
	}

	type ReactNode = boolean | null | number | ReactElement | string | undefined;

	type Ref<T> = ((instance: null | T) => void) | { current: null | T } | null;

	interface RefAttributes<T> {
		ref?: Ref<T>;
	}

	interface FunctionComponent<P = {}> {
		(props: P): ReactNode;
		displayName?: string;
	}

	type FC<P = {}> = FunctionComponent<P>;

	interface ComponentClass<P = {}> {
		new (props: P): Component<P>;
	}

	type ComponentType<P = {}> = ComponentClass<P> | FunctionComponent<P>;

	class Component<P = {}, S = {}> {
		constructor(props: P);
		readonly props: Readonly<P>;
		state: S;
		render(): ReactNode;
	}

	class PureComponent<P = {}, S = {}> extends Component<P, S> {}

	interface ExoticComponent<P = {}> {
		(props: P): ReactNode;
	}

	interface NamedExoticComponent<P = {}> extends ExoticComponent<P> {
		displayName?: string;
	}

	interface ForwardRefExoticComponent<P> extends NamedExoticComponent<P> {}

	type PropsWithChildren<P = unknown> = P & { children?: ReactNode };

	type PropsWithoutRef<P> = P extends any ? ("ref" extends keyof P ? Omit<P, "ref"> : P) : P;

	interface ForwardRefRenderFunction<T, P = {}> {
		(props: P, ref: Ref<T>): ReactNode;
	}

	function memo<P extends object>(component: FunctionComponent<P>): NamedExoticComponent<P>;

	function forwardRef<T, P = {}>(
		render: ForwardRefRenderFunction<T, P>,
	): ForwardRefExoticComponent<PropsWithoutRef<P> & RefAttributes<T>>;

	function createElement(type: unknown, props?: unknown, ...children: Array<ReactNode>): ReactElement;

	namespace JSX {
		interface Element extends ReactElement<any> {}
		interface ElementChildrenAttribute {
			children: {};
		}
		interface IntrinsicElements {
			div: { children?: ReactNode; className?: string };
		}
	}
}

export = React;
